#!/usr/bin/env python3
"""Export design assets; these tools do not form part of the product runtime."""
from pathlib import Path
import subprocess, json, hashlib, html
root = Path(__file__).resolve().parents[1] / 'design/assets/v1'
assets = []

def run(*args):
    subprocess.run(args, check=True, capture_output=True)
crops = {'brand-titlebar': ('main-light', 136, 44, 31, 37), 'brand-extract': ('extract-macos', 125, 136, 104, 122), 'folder': ('main-light', 397, 302, 42, 41), 'file-pdf': ('main-light', 397, 626, 44, 50), 'file-text': ('main-light', 398, 694, 43, 49), 'file-code': ('main-light', 397, 760, 47, 48), 'file-markdown': ('main-light', 397, 829, 47, 51), 'photo-lake-preview': ('main-light', 1198, 241, 350, 277), 'photo-lake-thumbnail': ('main-light', 397, 494, 45, 45), 'photo-sunrise-thumbnail': ('main-light', 397, 560, 45, 46), 'open': ('main-light', 48, 111, 32, 32), 'new': ('main-light', 174, 111, 28, 32), 'archive-test': ('main-light', 317, 110, 34, 34), 'more': ('main-light', 448, 111, 31, 31), 'search': ('main-light', 920, 111, 32, 32), 'settings': ('main-light', 1515, 43, 36, 34), 'view-list': ('main-light', 1000, 182, 46, 40), 'view-grid': ('main-light', 1065, 185, 28, 30), 'sort': ('main-light', 1114, 185, 36, 30), 'close': ('main-light', 1524, 192, 28, 27), 'check-selected': ('main-light', 337, 501, 30, 31), 'success': ('extract-macos', 141, 501, 43, 43), 'radio-selected': ('extract-macos', 142, 654, 42, 42), 'radio-unselected': ('extract-macos', 142, 934, 42, 43)}
for name, (source, x, y, w, h) in crops.items():
    target = root / 'slices' / f'{name}.png'
    run('magick', str(root / '../../hifi/v1/screens' / f'{source}.png'), '-crop', f'{w}x{h}+{x}+{y}', '+repage', str(target))
    assets.append(dict(id='slice/' + name, file=str(target.relative_to(root)), kind='original-pixel-crop', source='../../hifi/v1/screens/' + source + '.png', rect=[x, y, w, h], size=[w, h], background='baked source pixels; not transparent', usage='visual-reference' if not name.startswith('photo') else 'demo-image-only'))
paths = {'open': 'M3 8V5a1 1 0 0 1 1-1h5l3 3h8a1 1 0 0 1 1 1v2 M3 9h18l-2 11H3z', 'new': 'M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z M12 7v10 M7 12h10', 'archive-test': 'M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z M7 12l3 3 7-7', 'search': 'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0 M15 15l6 6', 'close': 'M6 6l12 12 M18 6L6 18', 'chevron-down': 'M6 9l6 6 6-6', 'chevron-right': 'M9 6l6 6-6 6', 'chevron-up': 'M6 15l6-6 6 6', 'check': 'M5 12l4 4L19 6', 'arrow-right': 'M4 12h16 M14 6l6 6-6 6', 'extract': 'M12 3v12 M7 10l5 5 5-5 M4 15v6h16v-6', 'view-list': 'M7 6h14 M7 12h14 M7 18h14 M3 6h.01 M3 12h.01 M3 18h.01', 'view-grid': 'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z', 'sort': 'M5 4v16 M2 17l3 3 3-3 M12 5h10 M12 10h8 M12 15h5 M12 20h2', 'sort-ascending': 'M12 20V4 M6 10l6-6 6 6', 'completed': 'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M7 12l3 3 7-7', 'external-open': 'M14 3h7v7 M21 3L10 14 M10 5H4v16h16v-6', 'minimize': 'M5 12h14', 'maximize': 'M5 5h14v14H5z', 'settings': 'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'}
colored = {'folder': '<defs><linearGradient id="f" x2="0" y2="1"><stop stop-color="#79bbff"/><stop offset="1" stop-color="#4796ef"/></linearGradient></defs><path fill="#2465ff" stroke="#2465ff" d="M3 4h6l3 3h8v12H3z"/><path fill="url(#f)" stroke="#428aff" d="M3 8h18v12H3z"/>', 'archive': '<defs><linearGradient id="a" x2="1" y2="1"><stop stop-color="#459aff"/><stop offset="1" stop-color="#1750ff"/></linearGradient></defs><path fill="url(#a)" stroke="none" d="M5 2h9l5 5v15H5a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z"/><path fill="#1748e7" stroke="none" d="M14 2v5h5z"/><path stroke="white" d="M10 4h2m-1 3h2m-3 3h2m-1 3h2m-3 3h3v4h-3z"/>', 'file-text': '<path fill="{paper}" stroke="{muted}" d="M5 2h9l5 5v15H5z M14 2v6h5 M8 11h8m-8 3h8m-8 3h8"/>', 'file-code': '<rect x="3" y="2" width="18" height="20" rx="2" fill="{paper}" stroke="{muted}"/><path d="m9 8-4 4 4 4m6-8 4 4-4 4m-2-10-2 12"/>', 'file-markdown': '<rect x="3" y="2" width="18" height="20" rx="2" fill="{paper}" stroke="{muted}"/><path d="M6 16V9l3 4 3-4v7m5-7v7m-2-2 2 2 2-2"/>', 'file-pdf': '<path fill="#fa3038" stroke="none" d="M5 2h9l5 5v15H5z"/><path stroke="white" d="M14 2v6h5"/><g stroke="white" stroke-width=".8"><path d="M7 19v-5h2v2H7 M11 19v-5h1.5l1 1v3l-1 1z M16 19v-5h2m-2 2h1.5"/></g>', 'more': '<circle cx="5" cy="12" r="1.5" fill="{ink}" stroke="none"/><circle cx="12" cy="12" r="1.5" fill="{ink}" stroke="none"/><circle cx="19" cy="12" r="1.5" fill="{ink}" stroke="none"/>'}
for theme, ink, paper, muted in [('light', '#20232a', '#ffffff', '#a4acbc'), ('dark', '#eceef3', '#20232a', '#8590a6')]:
    for name in list(paths) + list(colored):
        content = f'<path d="{paths[name]}"/>' if name in paths else colored[name].replace('{paper}', paper).replace('{muted}', muted).replace('{ink}', ink)
        svg = f'<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="{ink}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">{content}</svg>\n'
        target = root / 'svg' / theme / f'{name}.svg'
        target.write_text(svg)
        assets.append(dict(id=f'{theme}/{name}', file=str(target.relative_to(root)), kind='vector-reconstruction', logical_size=[24, 24], usage='candidate-ui-asset', theme=theme))
        for scale in [1, 2, 3]:
            dest = root / 'png' / theme / f'{name}@{scale}x.png'
for size in [32, 64, 128, 256, 512]:
    dest = root / 'brand' / f'archive-{size}.png'
    run('magick', str(root / 'brand/archive-generated-master.png'), '-resize', f'{size}x{size}', str(dest))
    assets.append(dict(id=f'brand/{size}', file=str(dest.relative_to(root)), kind='generative-transparent-reconstruction', size=[size, size], usage='candidate-brand-asset; not pixel-identical to source'))
for a in assets:
    a['sha256'] = hashlib.sha256((root / a['file']).read_bytes()).hexdigest()
(root / 'manifest.json').write_text(json.dumps(dict(version=1, source_coordinate_system='physical source pixels, top-left origin; rect = x,y,width,height', assets=assets), ensure_ascii=False, indent=2) + '\n')
cards = ''.join((f'''<div class="card"><img src="{html.escape(a['file'])}"><b>{html.escape(a['id'])}</b><small>{a['kind']}</small></div>''' for a in assets if a['kind'] == 'original-pixel-crop' or a['id'].startswith('light/') or a['id'] == 'brand/256'))
(root / 'index.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>xdzip 素材切图</title><style>body{margin:0;padding:32px;background:#f4f5f7;color:#20232a;font:14px system-ui}h1{font-size:28px}p{line-height:1.8;max-width:850px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:16px}.card{background:white;border:1px solid #dde1e9;border-radius:12px;padding:18px;display:flex;align-items:center;flex-direction:column;gap:14px;overflow:hidden}.card img{width:80px;height:80px;object-fit:contain;background:repeating-conic-gradient(#e7e9ed 0% 25%,#fff 0% 50%) 0/12px 12px}.card b{font-size:12px;overflow-wrap:anywhere}.card small{color:#6a7180;font-size:10px}a{color:#315fea}</style><h1>xdzip · 素材切图 v1</h1><p><a href="../../hifi/index.html">查看完整高保真原稿</a></p><p>原像素切片保留背景，用于对照；矢量与透明品牌图为重建候选，并非原图图层。PNG 提供 1× / 2× / 3×，SVG 提供浅色与深色版本。系统窗口按钮由平台绘制。<a href="manifest.json">素材清单与坐标</a></p><div class="grid">' + cards + '</div></html>')
print(json.dumps({'original_crops': len(crops), 'vector_designs': len(paths) + len(colored), 'svg_files': len(list((root / 'svg').rglob('*.svg'))), 'png_files': len(list(root.rglob('*.png')))}))
